X.add("functional","nivel-4-tonalidad-menor-funcional:Sensible y dominante",{"title": "E7→Am", "caption": "Sol♯ crea la sensible de La y tiende a subir a La; Re puede bajar a Do. La dominante menor tonal usa con frecuencia esta alteración.", "notes": "E3+G#3+B3+D4 A3+C4+E4"});
