X.add("functional","escalas-intervalos:Octava",{"title": "Do4 → Do5: doce semitonos", "notes": "C4 C5", "steps": ["Mismo nombre: Do", "Registro diferente", "12 semitonos = 6 tonos"], "caption": "La octava justa repite el nombre de nota en otro registro. Do4 y Do5 no son la misma altura, aunque pertenezcan a la misma clase de nota.", "use": "Entender dónde termina un ciclo de escala y cómo se relacionan 2/9, 4/11 y 6/13."});
