X.add("reading","Rúbrica breve",{"title": "Evaluar dimensiones distintas", "caption": "Una altura incorrecta y una interrupción del pulso requieren correcciones diferentes. Registra dónde ocurrió cada una.", "steps": ["Continuidad", "Alturas", "Ritmo", "Recuperación"]});
X.add("reading","Agrupar para anticipar",{"title": "Dos agrupaciones posibles del mismo compás", "caption": "El numerador por sí solo no elige el patrón. Sigue las barras, acentos e indicaciones del ejemplo.", "steps": ["5/8: 2+3", "5/8: 3+2"]});
X.add("reading","Acento no es volumen",{"title": "Métrica y ejecución pueden contrastar", "caption": "Un ataque en parte débil puede resaltarse sin cambiar la estructura del compás.", "steps": ["Posición fuerte", "Posición débil", "Acento expresivo"]});
X.add("reading","Pulso común",{"title": "Un inicio compartido, dos repartos", "caption": "En el mismo lapso, una voz divide en dos y otra en tres. La rejilla es una ayuda para comprender, no seis pulsos principales obligatorios.", "steps": ["2 contra 3", "Rejilla común: 6 partes", "2: posiciones 1 y 4", "3: posiciones 1, 3 y 5"]});
X.add("reading","De lo escrito a lo audible",{"title": "Construir la coordinación", "caption": "Mantén constante la duración del ciclo y comprueba que ambas voces vuelven juntas al inicio.", "steps": ["Cuenta 6 partes", "Marca cada 3", "Añade cada 2", "Escucha 2 contra 3"]});
X.add("reading","Mira antes de reaccionar",{"title": "Una nueva alteración cambia la referencia", "caption": "Lee qué nota se modifica y desde dónde rige. No presupongas que toda alteración anuncia una modulación.", "notes": "F4 F#4 G4"});
X.add("reading","Lectura responsable",{"title": "Tres niveles de información", "caption": "Comprueba la vigencia de la alteración antes de deducir el centro. Una nota cromática aislada no basta para cambiar la tonalidad.", "steps": ["Armadura local", "Alteración accidental", "Contexto tonal"]});
X.add("reading","Jerarquía de voces",{"title": "Una línea principal necesita continuidad", "caption": "Distingue la voz que lleva la idea de las voces de apoyo. El mayor volumen no siempre coincide con la nota más alta.", "notes": "C4 E4 G4 E4"});
X.add("reading","Acordes no sustituyen voces",{"title": "Dos líneas además de tres columnas", "caption": "Analizar los encuentros verticales no elimina el movimiento individual de cada parte.", "notes": "C4+E4 D4+F4 E4+G4"});
X.add("reading","Mapa antes de ensayo",{"title": "Trazar los saltos", "caption": "La primera vez se continúa al encontrar Al Coda; después de D.S. al Coda se vuelve al signo y se toma la salida indicada.", "steps": ["Inicio", "Segno", "Al Coda", "D.S. al Coda", "Segno", "Al Coda", "Coda"]});
X.add("reading","Entradas y silencios",{"title": "Preparar la entrada antes de tocar", "caption": "Una espera de varios compases sigue organizada por pulso y forma. Localiza una referencia que confirme el momento de entrada.", "steps": ["Cuenta compases", "Reconoce la señal", "Respira", "Entra"]});
X.add("reading","Protocolo profesional",{"title": "Un procedimiento repetible", "caption": "Busca una primera lectura informativa. La revisión posterior identifica qué practicar en detalle.", "steps": ["Vista previa", "Tempo viable", "Lectura continua", "Revisión"]});
X.add("reading","Cierre del curso",{"title": "Comparar el progreso", "caption": "Evalúa una dimensión a la vez: precisión, continuidad, expresión o recuperación.", "steps": ["Evidencia inicial", "Lectura final", "Errores localizados", "Próximo objetivo"]});
X.add("jazz","Ruta del nivel 1: preparación y diagnóstico",{"title": "Antes de practicar este nivel", "steps": ["Recupera el nivel anterior", "Nombra el material nuevo", "Lee un ejemplo", "Escucha y compara", "Pasa a la práctica"], "caption": "La preparación y el diagnóstico permiten elegir una dificultad adecuada. Identifica primero qué cambia en el material de este nivel."});
X.add("jazz","1.1 Cifrado de acordes jazz",{"title": "Cmaj7, Cm7 y C7 en pentagrama", "caption": "La fundamental Do permanece. Cmaj7 lleva Mi y Si; Cm7, Mi♭ y Si♭; C7, Mi y Si♭. Tercera y séptima distinguen las calidades.", "notes": "C4+E4+G4+B4 C4+Eb4+G4+Bb4 C4+E4+G4+Bb4", "compare": [{"label": "Semidisminuido: Cm7♭5", "notes": "C4+Eb4+Gb4+Bb4"}, {"label": "Disminuido: Cdim7", "notes": "C4+Eb4+Gb4+Bbb4"}]});
X.add("jazz","1.1b Laboratorio de acordes, escalas y arpegios",{"title": "Escala, arpegio y acorde no son la misma tarea", "caption": "Una escala recorre la colección por pasos; el arpegio de Cmaj7 elige Do–Mi–Sol–Si sucesivos; el acorde los reúne. Usa el laboratorio después de reconocer qué selección haces.", "notes": "C4 D4 E4 G4 B4 C5"});
X.add("jazz","1.2 Campo armónico mayor con tétradas",{"title": "Tétradas de Do mayor", "caption": "Apila 1–3–5–7 diatónicos desde cada grado. El acorde del VII tiene quinta disminuida; no es Bm7.", "steps": ["Cmaj7", "Dm7", "Em7", "Fmaj7", "G7", "Am7", "Bm7♭5"]});
X.add("jazz","1.3 El ii-V-I mayor",{"title": "ii–V–I: bajo y notas guía", "caption": "Dm7→G7→Cmaj7 comparte Fa entre ii y V; Do baja a Si y luego Fa a Mi. Observa movimientos concretos, no solo símbolos.", "notes": "D4+F4+C5 G3+B3+F4 C4+E4+B4"});
X.add("jazz","1.4 Extensiones diatónicas básicas",{"title": "9 de Cmaj7 y 13 de G7", "caption": "Re es 9 de Do; Mi es 13 de Sol. La misma nota puede ser extensión de un acorde y nota estructural de otro.", "notes": "C4+E4+B4+D5 G3+B3+F4+E5"});
X.add("jazz","1.5 Voicings shell: guide tones",{"title": "Shells: tercera y séptima", "caption": "En ii–V–I de Do estas guías bastan para mostrar dos resoluciones por semitono. La fundamental puede estar a cargo del bajo.", "notes": "F4+C5 F4+B4 E4+B4"});
X.add("jazz","1.6 Inversiones y bajo (slash chords)",{"title": "C frente a C/E", "caption": "Mi en el bajo produce primera inversión. Un acorde slash también puede indicar un bajo ajeno a la tríada; no todos los slash son inversiones.", "notes": "C4+E4+G4 E3+G4+C5"});
X.add("jazz","1.7 Relación básica acorde-escala",{"title": "Re dórico sobre Dm7 en Do mayor", "caption": "Re–Fa–La–Do son notas de Dm7. Mi, Sol y Si completan la colección dórica; su uso como tensiones depende del fraseo.", "notes": "D4 E4 F4 G4 A4 B4 C5 D5"});
X.add("jazz","1.8 Lectura de lead sheets y el Real Book",{"title": "Qué aporta un lead sheet", "caption": "Cifrado y melodía son información complementaria. El símbolo no prescribe un voicing completo ni toda la rítmica de acompañamiento.", "steps": ["Melodía escrita", "Cifrado sobre el compás", "Forma y repeticiones", "Interpretación"]});
X.add("jazz","1.9 Funciones armónicas: tónico, subdominante y dominante",{"title": "Una lectura funcional de ii–V–I", "caption": "La función describe una relación dentro de una tonalidad y una frase, no una propiedad fija del símbolo en cualquier pieza.", "steps": ["Dm7: preparación", "G7: dominante", "Cmaj7: tónica"]});
X.add("jazz","1.9b Ritmo armónico y peso métrico",{"title": "Ritmo armónico básico", "caption": "Si Dm7 y G7 comparten un compás con dos pulsos cada uno, se acelera la frecuencia de cambios aunque el BPM permanezca igual.", "steps": ["Compás 1: Dm7, 4 pulsos", "Compás 2: G7, 4 pulsos", "Compás 3: Cmaj7, 4 pulsos"]});
X.add("jazz","1.9c Relación melodía–armonía y notas disponibles",{"title": "La sobre C: sexta/13 como color", "caption": "Do–Mi–Sol son notas de la tríada; La aporta un color posible. Posición rítmica y resolución ayudan a distinguir apoyo, paso y tensión.", "notes": "C4 E4 G4 A4 G4"});
X.add("jazz","1.10 Repertorio recomendado del Real Book — Nivel 1",{"title": "Cómo estudiar una pieza de referencia", "steps": ["Forma y centros", "Cifrado y melodía", "Una célula armónica", "Guías y bajo", "Aplicación en contexto"], "caption": "Localiza el recurso del nivel en una sección concreta de la pieza. Un esquema de estudio no sustituye una partitura autorizada ni convierte toda la obra en una sola fórmula."});
X.add("jazz","Proyecto aplicado del nivel 1",{"title": "Del concepto al proyecto", "steps": ["Elige una célula del nivel", "Escribe notas y grados", "Conduce las voces", "Prueba en la forma", "Registra y revisa"], "caption": "La evidencia del proyecto debe mostrar una decisión armónica explicada, no solo un resultado ejecutado. Usa los ejemplos de este nivel como punto de partida."});
X.add("jazz","Ruta del nivel 2: preparación y diagnóstico",{"title": "Antes de practicar este nivel", "steps": ["Recupera el nivel anterior", "Nombra el material nuevo", "Lee un ejemplo", "Escucha y compara", "Pasa a la práctica"], "caption": "La preparación y el diagnóstico permiten elegir una dificultad adecuada. Identifica primero qué cambia en el material de este nivel."});
X.add("jazz","2.1 Campo armónico menor",{"title": "La menor natural y sus cambios frecuentes", "caption": "Elevar Sol a Sol♯ crea menor armónica; elevar además Fa a Fa♯ da menor melódica ascendente. Identifica de qué material sale cada acorde.", "notes": "A3 B3 C4 D4 E4 F4 G4 A4"});
X.add("jazz","2.2 El ii-V-i menor",{"title": "iiø–V–i en La menor", "caption": "Bm7♭5→E7→Am: Fa natural pertenece a iiø y Sol♯ crea sensible en el dominante. No reemplaces iiø por Bm7 sin cambiar el color.", "notes": "B3+D4+F4+A4 E3+G#3+D4 A3+C4+E4"});
X.add("jazz","2.3 Dominantes secundarios",{"title": "D7→G7: dominante de la dominante", "caption": "Fa♯ no pertenece a Do mayor, pero es tercera de D7 y conduce hacia Sol. D7 puede analizarse como V7/V en ese contexto.", "notes": "D4+F#4+A4+C5 G3+B3+D4+F4"});
X.add("jazz","2.4 Sustitución tritonal",{"title": "G7 y D♭7 comparten un tritono enarmónico", "caption": "Si–Fa de G7 corresponde a Do♭–Fa de D♭7. El bajo puede bajar cromáticamente Re♭→Do hacia Cmaj7.", "notes": "G3+B3+F4 Db3+F4+Cb5 C3+E4+B4"});
X.add("jazz","2.5 Modos y relación acorde-escala",{"title": "Do lidio: cuarto grado elevado", "caption": "Fa♯ distingue lidio de la escala mayor natural de Do. La elección acorde–escala responde al contexto, no solo al nombre del modo.", "notes": "C4 D4 E4 F#4 G4 A4 B4 C5"});
X.add("jazz","2.6 El blues de 12 compases",{"title": "Blues básico de doce compases", "caption": "Cada bloque enumera cuatro compases. En Do: I7=C7, IV7=F7, V7=G7. Existen muchas variantes de esta forma.", "steps": ["I7 I7 I7 I7", "IV7 IV7 I7 I7", "V7 IV7 I7 V7"]});
X.add("jazz","2.7 ii-V encadenados y ciclo de quintas",{"title": "Dos ii–V encadenados", "caption": "El primer par apunta hacia Re; el segundo hacia Do. Sigue las terceras de los dominantes para reconocer los destinos.", "steps": ["Em7–A7", "Dm7–G7", "Cmaj7"]});
X.add("jazz","2.8 Campo armónico completo: menor armónica y menor melódica",{"title": "Armonizar la menor armónica conserva Sol♯", "caption": "Apila terceras desde cada grado sin sustituir la sensible por Sol natural. La colección determina las calidades resultantes.", "notes": "A3 B3 C4 D4 E4 F4 G#4 A4"});
X.add("jazz","2.9 Acordes disminuidos de paso y de función común",{"title": "C♯dim7 conecta C y Dm", "caption": "Do♯ asciende a Re mientras otras voces avanzan poco. El análisis de un disminuido de paso depende de su llegada y conducción.", "notes": "C4+E4+G4 C#4+E4+G4+Bb4 D4+F4+A4"});
X.add("jazz","2.10 Tipos de cadencia: auténtica, plagal, semicadencia y deceptiva",{"title": "La cadencia se define por el destino", "caption": "En Do, G→Am evita la llegada esperada a C. No se identifican todas las cadencias solo por la calidad del último acorde.", "steps": ["V→I: auténtica", "IV→I: plagal", "terminar en V: semicadencia", "V→vi: deceptiva"]});
X.add("jazz","2.10b Modos completos de la menor melódica",{"title": "Re menor melódica: referencia para sus modos", "caption": "Sus notas generan los modos al cambiar el punto de referencia. Mantén la misma colección al rotarla; no conviertas cada modo en una escala mayor.", "notes": "D4 E4 F4 G4 A4 B4 C#5 D5"});
X.add("jazz","2.10c Escala mayor armónica y cuatro centros tonales",{"title": "Do mayor armónica: sexto grado menor", "caption": "La♭ distingue esta escala de Do mayor natural. El tramo La♭–Si tiene tres semitonos, una segunda aumentada escrita.", "notes": "C4 D4 E4 F4 G4 Ab4 B4 C5"});
X.add("jazz","2.11 Repertorio recomendado del Real Book — Nivel 2",{"title": "Cómo estudiar una pieza de referencia", "steps": ["Forma y centros", "Cifrado y melodía", "Una célula armónica", "Guías y bajo", "Aplicación en contexto"], "caption": "Localiza el recurso del nivel en una sección concreta de la pieza. Un esquema de estudio no sustituye una partitura autorizada ni convierte toda la obra en una sola fórmula."});
