X.add("jazz","Ruta del nivel 3: preparación y diagnóstico",{"title": "Antes de practicar este nivel", "steps": ["Recupera el nivel anterior", "Nombra el material nuevo", "Lee un ejemplo", "Escucha y compara", "Pasa a la práctica"], "caption": "La preparación y el diagnóstico permiten elegir una dificultad adecuada. Identifica primero qué cambia en el material de este nivel."});
X.add("jazz","3.1 Intercambio modal",{"title": "iv menor prestado: Fm→C", "caption": "La♭ no pertenece a Do mayor natural. El préstamo desde Do menor paralelo colorea la llegada mediante La♭→Sol.", "notes": "F3+Ab3+C4 C4+E4+G4"});
X.add("jazz","3.2 Dominantes sustitutos extendidos",{"title": "Sustituto tritonal en una progresión", "caption": "D♭7 toma el lugar de G7 en esta variante. Comprueba que la melodía y las voces internas admitan el cambio.", "steps": ["Dm7", "D♭7", "Cmaj7"]});
X.add("jazz","3.3 Técnicas básicas de reharmonización",{"title": "Rearmonizar conservando notas de melodía", "caption": "C y Am comparten Do y Mi, pero cambian bajo y función percibida. Que compartan notas no vuelve intercambiable toda aparición.", "notes": "C4+E4+G4 A3+C4+E4"});
X.add("jazz","3.4 Turnarounds",{"title": "Turnaround I–VI7–ii–V", "caption": "A7 añade Do♯ para dirigirse a Dm7. La célula prepara el regreso al comienzo.", "steps": ["Cmaj7", "A7", "Dm7", "G7"]});
X.add("jazz","3.5 Forma AABA y rhythm changes",{"title": "AABA: treinta y dos compases", "caption": "La letra describe una sección, no un acorde. Rhythm changes es una familia armónica asociada a una forma AABA, con numerosas variantes.", "steps": ["A: 8 compases", "A: 8", "B: 8", "A: 8"]});
X.add("jazz","3.6 Escalas simétricas sobre dominantes alterados",{"title": "Tonos enteros: seis pasos iguales", "caption": "Do–Re–Mi–Fa♯–Sol♯–La♯ usa 2 semitonos entre vecinos. La simetría produce un color diferente del patrón mayor.", "notes": "C4 D4 E4 F#4 G#4 A#4 C5"});
X.add("jazz","3.6b La escala y los acordes octatónicos",{"title": "Octatónica semitono–tono desde Do", "caption": "Alterna 1–2 semitonos y reúne ocho alturas. No la confundas con la escala por tonos enteros, que tiene seis.", "notes": "C4 Db4 Eb4 E4 F#4 G4 A4 Bb4"});
X.add("jazz","3.7 Voicings sin fundamental (rootless) — sistema A/B",{"title": "Dos disposiciones rootless de Dm9", "caption": "Sobre bajo Re, Fa–La–Do–Mi aporta ♭3–5–♭7–9. Reordenar esas voces cambia la disposición, no el acorde de referencia.", "notes": "F3+A3+C4+E4 C4+E4+F4+A4"});
X.add("jazz","3.8 Clichés de línea (line clichés)",{"title": "Una línea cromática sobre La menor", "caption": "Sol♯→Sol→Fa♯ introduce movimiento mientras parte de la tríada permanece. Identifica qué voz cambia y cuáles se sostienen.", "notes": "A3+C4+E4 A3+C4+E4+G#4 A3+C4+E4+G4 A3+C4+E4+F#4"});
X.add("jazz","3.9 Ciclo de Coltrane y sustituciones por terceras mayores",{"title": "Centros separados por terceras mayores", "caption": "Si, Sol y Mi♭ dividen la octava por terceras mayores; cada dominante prepara el centro siguiente. Es una célula de estudio, no una transcripción completa.", "steps": ["Bmaj7", "D7", "Gmaj7", "B♭7", "E♭maj7", "F♯7", "Bmaj7"]});
X.add("jazz","3.10 Constant structure (CSCP)",{"title": "Estructura constante: tres tríadas mayores", "caption": "Mantén la calidad y desplaza el conjunto. Fa♯ y Sol♯ muestran que no se conserva una sola escala diatónica de Do.", "notes": "C4+E4+G4 D4+F#4+A4 E4+G#4+B4"});
X.add("jazz","3.11 Modulación: directa y por acorde pivote",{"title": "Am como posible acorde pivote", "caption": "Am puede ser vi en Do e ii en Sol. D7 y una llegada convincente a G apoyan la nueva lectura; un acorde común por sí solo no prueba una modulación.", "steps": ["Do mayor: C", "Am", "D7", "G", "Sol mayor"]});
X.add("jazz","3.11b Cromatismo modal y sustitución escalar",{"title": "Do dórico ♭2: cambiar una colección", "caption": "La segunda Re♭ y la tercera Mi♭ colorean el material. Conecta cualquier sustitución escalar con las notas del acorde y la melodía.", "notes": "C4 Db4 Eb4 F4 G4 A4 Bb4 C5"});
X.add("jazz","3.11c Rearmonización desde la melodía",{"title": "Una misma nota superior: Mi", "caption": "Mi puede ser tercera de C o quinta de Am. Mantener la melodía permite comparar dos apoyos armónicos distintos.", "notes": "E4 C4+E4+G4 A3+C4+E4"});
X.add("jazz","3.12 Repertorio recomendado del Real Book — Nivel 3",{"title": "Cómo estudiar una pieza de referencia", "steps": ["Forma y centros", "Cifrado y melodía", "Una célula armónica", "Guías y bajo", "Aplicación en contexto"], "caption": "Localiza el recurso del nivel en una sección concreta de la pieza. Un esquema de estudio no sustituye una partitura autorizada ni convierte toda la obra en una sola fórmula."});
X.add("jazz","Proyecto aplicado del nivel 3",{"title": "Del concepto al proyecto", "steps": ["Elige una célula del nivel", "Escribe notas y grados", "Conduce las voces", "Prueba en la forma", "Registra y revisa"], "caption": "La evidencia del proyecto debe mostrar una decisión armónica explicada, no solo un resultado ejecutado. Usa los ejemplos de este nivel como punto de partida."});
X.add("jazz","Ruta del nivel 4: preparación y diagnóstico",{"title": "Antes de practicar este nivel", "steps": ["Recupera el nivel anterior", "Nombra el material nuevo", "Lee un ejemplo", "Escucha y compara", "Pasa a la práctica"], "caption": "La preparación y el diagnóstico permiten elegir una dificultad adecuada. Identifica primero qué cambia en el material de este nivel."});
X.add("jazz","4.1 Armonía cuartal y quintal",{"title": "Cuartas frente a quintas", "caption": "Do–Fa–Si♭ apila cuartas justas; Do–Sol–Re apila quintas. No las analices automáticamente como tríadas por terceras.", "notes": "C4+F4+Bb4 C4+G4+D5"});
X.add("jazz","4.2 Estructuras superiores y polichords",{"title": "Tríada de Re sobre soporte de C7", "caption": "Re–Fa♯–La aporta 9–♯11–13 respecto a Do. Mi–Si♭ conserva las guías del dominante.", "notes": "C3+E4+Bb4 D5+F#5+A5"});
X.add("jazz","4.3 Armonía no funcional y pandiatonicismo",{"title": "Notas diatónicas sin pila de terceras", "caption": "Todas pertenecen a Do mayor, pero la disposición no forma una tríada completa apilada. Pandiatonicismo y ausencia de función fuerte no significan ausencia de organización.", "notes": "C4+D4+E4+G4"});
X.add("jazz","4.4 Escalas modales contemporáneas",{"title": "Do lidio aumentado: 1–2–3–♯4–♯5–6–7", "caption": "La cuarta Fa♯ y la quinta Sol♯ lo distinguen de Do mayor. Es el tercer modo de La menor melódica: verifica la colección en lugar de asociar el nombre a cualquier acorde.", "notes": "C4 D4 E4 F#4 G#4 A4 B4 C5"});
X.add("jazz","4.5 Fundamentos de composición jazz",{"title": "Componer una idea que tenga dirección", "caption": "Esta breve curva vuelve a Do. Desarrolla un motivo cambiando ritmo, registro o final, y comprueba qué identidad permanece.", "notes": "C4 D4 E4 G4 E4 D4 C4"});
X.add("jazz","4.6 Drop voicings para piano y guitarra (drop 2, drop 3, drop 2&4, drop 2&3)",{"title": "Drop 2: bajar la segunda voz desde arriba", "caption": "En Do–Mi–Sol–Si la segunda voz es Sol. Bajarla una octava produce Sol3–Do4–Mi4–Si4, manteniendo las clases de altura.", "notes": "C4+E4+G4+B4 G3+C4+E4+B4"});
X.add("jazz","4.7 Armonía modal compositiva (acordes estáticos, color por escala)",{"title": "Un centro modal en Re dórico", "caption": "La colección coincide con Do mayor, pero una referencia persistente a Re cambia la orientación. No fuerces una cadencia V–I para justificar todo pasaje modal.", "notes": "D4 E4 F4 G4 A4 B4 C5 D5"});
X.add("jazz","4.8 Pedal de bajo y pedal armónico",{"title": "Pedal Do bajo acordes cambiantes", "caption": "El bajo se mantiene mientras cambian las voces superiores. Distingue el pedal sostenido de una sucesión de fundamentales distintas.", "notes": "C3+D4+F4 C3+E4+G4 C3+F4+A4"});
X.add("jazz","4.9 Armonía negativa",{"title": "Una reflexión de clases de altura", "caption": "Este ejemplo fija un eje concreto. Cambiar el eje cambia el resultado; la armonía negativa es una transformación, no una regla obligatoria de sustitución.", "steps": ["Eje Do–Sol", "Do ↔ Sol", "Re ↔ Fa", "Mi ↔ Mi♭"]});
X.add("jazz","4.10 Acordes de función especial",{"title": "♭II como color previo a I", "caption": "D♭ mayor introduce Re♭ y La♭ en Do. El nombre funcional depende de cómo se prepara y conduce, no solo de ser un acorde ajeno a la armadura.", "notes": "Db4+F4+Ab4 C4+E4+G4"});
X.add("jazz","4.11 Acordes compuestos: sobre bajo, inversión, híbrido y acorde sobre acorde",{"title": "Tres lecturas que no son equivalentes", "caption": "Una barra oblicua suele separar acorde y bajo. Dos acordes superpuestos requieren identificar las notas de ambos, no confundir todo símbolo slash con un poliacorde.", "steps": ["C/E: inversión", "D/C: tríada sobre bajo", "D sobre C: dos estructuras"]});
X.add("jazz","4.12 Conducción de voces básica para arreglo",{"title": "Continuidad antes de densidad", "caption": "Fa se mantiene entre los dos primeros acordes; Do→Si y Fa→Mi completan el enlace. Distribuye las voces para conservar independencia y registro.", "notes": "F4+C5 F4+B4 E4+B4"});
X.add("jazz","4.12b Triad pairs y permutaciones",{"title": "Par de tríadas C y D", "caption": "Cada grupo aporta tres notas; juntas forman una colección de seis alturas. La permutación cambia el orden, no necesariamente el conjunto.", "notes": "C4 E4 G4 D4 F#4 A4"});
X.add("jazz","4.12c Armonización desde la voz superior y ostinato",{"title": "Armonizar una voz superior Sol–Sol–Do", "caption": "La voz de arriba guía las elecciones. Comprueba por separado el bajo y las voces internas, aunque la melodía mantenga una nota.", "notes": "C4+E4+G4 D4+F4+G4 E4+G4+C5"});
X.add("jazz","4.13 Repertorio recomendado del Real Book — Nivel 4",{"title": "Cómo estudiar una pieza de referencia", "steps": ["Forma y centros", "Cifrado y melodía", "Una célula armónica", "Guías y bajo", "Aplicación en contexto"], "caption": "Localiza el recurso del nivel en una sección concreta de la pieza. Un esquema de estudio no sustituye una partitura autorizada ni convierte toda la obra en una sola fórmula."});
