X.add("jazz","5.1 Pentatónicas, blues y superposiciones",{"title": "Pentatónica menor más ♭5: escala blues", "caption": "La pentatónica Do–Mi♭–Fa–Sol–Si♭ añade Sol♭ como color blues. Su uso expresivo no se reduce a subir y bajar la escala.", "notes": "C4 Eb4 F4 Gb4 G4 Bb4 C5"});
X.add("jazz","5.2 Swing, articulación y anticipación",{"title": "Swing no es siempre una proporción fija", "caption": "La relación entre las dos partes cambia con tempo, intérprete y contexto. Escucha un modelo antes de convertirlo en una cuantización rígida.", "steps": ["Dos corcheas escritas", "Relación temporal variable", "Articulación del estilo"]});
X.add("jazz","5.3 Cromatismo y vocabulario bebop",{"title": "Aproximación cromática hacia Mi", "caption": "Re♯ conduce por semitono a Mi. La nota cromática adquiere sentido por su destino y su posición rítmica, no por quedar siempre permitida o prohibida.", "notes": "D4 D#4 E4 G4"});
X.add("jazz","5.4 Notas objetivo y líneas de guide tones",{"title": "Objetivos de guía en ii–V–I", "caption": "Fa es tercera de Dm7 y séptima de G7; Mi es tercera de Cmaj7. Planifica una línea que llegue a estas alturas en momentos de apoyo.", "notes": "F4 F4 E4"});
X.add("jazz","5.5 Desarrollo motívico y permutaciones",{"title": "Ascenso e inversión del contorno", "caption": "Do–Re–Mi asciende; Mi–Re–Do desciende. El desarrollo necesita un rasgo reconocible, no solo una nueva colección aleatoria.", "notes": "C4 D4 E4 E4 D4 C4"});
X.add("jazz","5.6 Improvisación sobre ii–V–I y turnarounds",{"title": "Un objetivo por acorde", "caption": "Canta primero las tres notas guía de destino. Después conecta entre ellas sin perder la duración de cada acorde.", "steps": ["Dm7: Fa", "G7: Si", "Cmaj7: Mi"]});
X.add("jazz","5.7 Triad pairs, cuartas y recursos outside",{"title": "Desplazar y regresar", "caption": "Tras una tríada de Do aparece una de Re♭ y se vuelve a Do. El contraste outside se entiende por la referencia y el retorno, no por tocar al azar fuera de la escala.", "notes": "C4 E4 G4 Db4 F4 Ab4 C4"});
