X.add("jazz","5.10 Referencia rápida de escalas y voicings",{"title": "Cmaj9 como referencia reducida", "caption": "Do–Mi–Si–Re muestra fundamental, tercera, séptima y novena. Relaciona la forma del voicing con sus grados, no solo con su imagen en el teclado.", "notes": "C4+E4+B4+D5"});
X.add("jazz","5.11 Walking bass y construcción de líneas",{"title": "Walking: un ataque por pulso", "caption": "El primer grupo perfila C y usa Sol♭ para acercarse a Fa. La línea debe conectar los acordes reales y sostener el pulso; no toda nota del bajo es una fundamental.", "notes": "C3 E3 G3 Gb3 F3 A3 C4 B2"});
